import { readFile, writeFile } from "node:fs/promises";

const here = import.meta.url;
const tokens = JSON.parse(await readFile(new URL("tokens.json", here), "utf8"));
const colors = ["surface", "subtle", "text", "muted", "line", "onAccent"];
const sizes = ["spacing", "radius", "bodySize", "labelSize"];
const paletteColors = ["accent", "sidebar", "selection", "surface"];
const palettes = Object.entries(tokens.palettes);
const defaults = tokens.palettes[tokens.defaultPalette];
const pair = values => `light-dark(${values.join(", ")})`;
const css = [
  "/* Generated by apps/design/generate.mjs. */",
  ":root {",
  ...colors.filter(name => !paletteColors.includes(name)).map(name => `  --${name}: ${pair(tokens[name])};`),
  ...sizes.map(name => `  --${name}: ${tokens[name]}px;`),
  ...paletteColors.map(name => `  --${name}: ${pair(defaults[name])};`),
  "}",
  ...palettes.map(([id, palette]) => `:root[data-accent="${id}"] { ${paletteColors.map(name => `--${name}: ${pair(palette[name])};`).join(" ")} }`),
].join("\n") + "\n";
const swiftPair = values => `(0x${values[0].slice(1)}, 0x${values[1].slice(1)})`;
const swift = [
  "// Generated by apps/design/generate.mjs.",
  "import SwiftUI",
  "",
  "enum BasketTokens {",
  ...colors.map(name => `    static let ${name}: (UInt32, UInt32) = ${swiftPair(tokens[name])}`),
  ...sizes.map(name => `    static let ${name}: CGFloat = ${tokens[name]}`),
  "    struct Palette: Identifiable {",
  "        let id: String",
  "        let label: String",
  ...paletteColors.map(name => `        let ${name}: (UInt32, UInt32)`),
  "    }",
  `    static let defaultPalette = "${tokens.defaultPalette}"`,
  "    static let palettes: [Palette] = [",
  ...palettes.map(([id, palette]) => `        .init(id: "${id}", label: ${JSON.stringify(palette.label)}, ${paletteColors.map(name => `${name}: ${swiftPair(palette[name])}`).join(", ")}),`),
  "    ]",
  "    static let paletteAliases: [String: String] = [",
  ...Object.entries(tokens.paletteAliases).map(([old, id]) => `        "${old}": "${id}",`),
  "    ]",
  "}",
].join("\n") + "\n";
const paletteJS = [
  "// Generated by apps/design/generate.mjs.",
  `export const defaultPalette = "${tokens.defaultPalette}";`,
  `export const palettes = ${JSON.stringify(palettes.map(([id, {label}]) => ({id, label})), null, 2)};`,
  `const aliases: Record<string, string> = ${JSON.stringify(tokens.paletteAliases, null, 2)};`,
  "export function paletteID(id: string): string {",
  "  const resolved = Object.hasOwn(aliases, id) ? aliases[id] : id;",
  "  return palettes.some(palette => palette.id === resolved) ? resolved : defaultPalette;",
  "}",
].join("\n") + "\n";
const outputs = [
  ["../chrome/src/palettes.ts", paletteJS],
  ["../chrome/tokens.css", css],
  ["../macos/Sources/FeedBasket/Tokens.swift", swift],
];
for (const [path, contents] of outputs) {
  const url = new URL(path, here);
  if (process.argv.includes("--check")) {
    if (await readFile(url, "utf8") !== contents) throw new Error(`${path} needs regeneration`);
  } else {
    await writeFile(url, contents);
  }
}
